import {useEffect,useMemo,useState} from 'react';
import {CalendarClock,PackageCheck,Plus,RefreshCw,UsersRound,X} from 'lucide-react';
import {assignClientPackage,createServicePackage,listClientPackages,listRenewalSignals,listServicePackages,updateServicePackage} from '../../lib/practiceOperationsApi';

const emptyPackage={name:'',profession_code:'',capability_code:'',description:'',session_allowance:6,duration_days:42,price:'',currency:'INR',active:true};
const today=()=>new Date().toISOString().slice(0,10);
const plusDays=days=>{const value=new Date();value.setDate(value.getDate()+Number(days||0));return value.toISOString().slice(0,10);};
const money=item=>item.price_minor==null?'Optional price':new Intl.NumberFormat(undefined,{style:'currency',currency:item.currency}).format(item.price_minor/100);

export function ExternalPackages({clients=[]}){
  const [packages,setPackages]=useState([]);const [assignments,setAssignments]=useState([]);const [signals,setSignals]=useState([]);
  const [state,setState]=useState('loading');const [error,setError]=useState('');const [editor,setEditor]=useState(null);const [assignment,setAssignment]=useState(null);
  const load=async()=>{setState('loading');setError('');try{const [library,clientPackages,renewals]=await Promise.all([listServicePackages(true),listClientPackages(),listRenewalSignals()]);setPackages(library.items||[]);setAssignments(clientPackages.items||[]);setSignals(renewals.items||[]);setState('ready');}catch(reason){setError(reason.message||'Packages could not be loaded.');setState('error');}};
  useEffect(()=>{void load();},[]);
  const active=packages.filter(item=>item.active);
  const metrics=useMemo(()=>[
    ['Active packages',active.length,PackageCheck],['Client programmes',assignments.filter(item=>item.status==='ACTIVE').length,UsersRound],
    ['Renewals due',signals.filter(item=>item.signal==='RENEWAL_DUE').length,RefreshCw],['Packages ending soon',signals.filter(item=>item.signal==='PACKAGE_ENDING_SOON'||item.signal==='SESSIONS_LOW').length,CalendarClock],
  ],[active.length,assignments,signals]);
  const save=async event=>{event.preventDefault();setError('');try{const payload={...editor.form,profession_code:editor.form.profession_code||null,capability_code:editor.form.capability_code||null,description:editor.form.description||null,session_allowance:Number(editor.form.session_allowance),duration_days:Number(editor.form.duration_days),price_minor:editor.form.price===''?null:Math.round(Number(editor.form.price)*100),currency:editor.form.price===''?null:editor.form.currency};delete payload.price;if(editor.item)await updateServicePackage(editor.item.id,{...payload,expected_version:editor.item.current_version});else await createServicePackage(payload);setEditor(null);await load();}catch(reason){setError(reason.message||'Package could not be saved.');}};
  const assign=async event=>{event.preventDefault();setError('');try{await assignClientPackage({...assignment,package_id:assignment.package_id,client_id:assignment.client_id,sessions_total:assignment.sessions_total?Number(assignment.sessions_total):null,renewal_date:assignment.renewal_date||null,notes:assignment.notes||null});setAssignment(null);await load();}catch(reason){setError(reason.message||'Package could not be assigned.');}};
  return <div className="space-y-6"><section className="flex flex-col justify-between gap-4 rounded-[28px] bg-slate-950 p-6 text-white sm:flex-row sm:items-end sm:p-8"><div><p className="text-xs font-bold uppercase tracking-[.2em] text-blue-300">Practice growth</p><h2 className="mt-2 text-3xl font-bold">Packages &amp; programmes</h2><p className="mt-2 max-w-2xl text-sm text-slate-300">Define structured services, assign them to clients, and act on renewal signals. Renewal always remains a practitioner decision.</p></div><button onClick={()=>setEditor({form:emptyPackage,item:null})} className="min-h-11 rounded-xl bg-white px-4 text-sm font-bold text-slate-950"><Plus className="mr-2 inline" size={16}/>Create package</button></section>
    {error&&<div role="alert" className="rounded-2xl border border-red-200 bg-red-50 p-4 text-sm text-red-800">{error}<button onClick={load} className="ml-3 font-bold underline">Retry</button></div>}
    <section className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{metrics.map(([label,value,Icon])=><article key={label} className="rounded-3xl border border-slate-200 bg-white p-5"><Icon className="text-blue-700"/><p className="mt-5 text-3xl font-bold">{state==='loading'?'—':value}</p><p className="mt-1 text-sm text-slate-600">{label}</p></article>)}</section>
    <div className="grid gap-6 xl:grid-cols-[1.15fr_.85fr]"><section className="rounded-3xl border border-slate-200 bg-white p-5 sm:p-6"><div className="flex items-center justify-between"><div><h3 className="text-xl font-bold">Package library</h3><p className="mt-1 text-sm text-slate-500">Reusable definitions; existing assignments retain their assigned version.</p></div></div><div className="mt-5 space-y-3">{packages.map(item=><article key={item.id} className="rounded-2xl border border-slate-200 p-4"><div className="flex flex-col justify-between gap-3 sm:flex-row"><div><div className="flex items-center gap-2"><h4 className="font-bold">{item.name}</h4><span className={`rounded-full px-2 py-1 text-[10px] font-bold ${item.active?'bg-emerald-50 text-emerald-700':'bg-slate-100 text-slate-500'}`}>{item.active?'ACTIVE':'INACTIVE'}</span></div><p className="mt-1 text-sm text-slate-500">{item.session_allowance} sessions · {item.duration_days} days · {money(item)}</p><p className="mt-2 text-sm text-slate-600">{item.description||'No description provided.'}</p></div><div className="flex shrink-0 gap-2"><button onClick={()=>setAssignment({client_id:'',package_id:item.id,start_date:today(),end_date:plusDays(item.duration_days),status:'ACTIVE',sessions_total:item.session_allowance,renewal_date:'',notes:''})} disabled={!item.active||clients.length===0} className="min-h-11 rounded-xl bg-blue-700 px-3 text-xs font-bold text-white disabled:opacity-40">Assign</button><button onClick={()=>setEditor({item,form:{...item,price:item.price_minor==null?'':item.price_minor/100}})} className="min-h-11 rounded-xl border px-3 text-xs font-bold">Edit</button></div></div></article>)}{state==='ready'&&!packages.length&&<p className="rounded-2xl border border-dashed p-8 text-center text-sm text-slate-500">Create the first package for this practice.</p>}</div></section>
      <section className="rounded-3xl border border-slate-200 bg-white p-5 sm:p-6"><h3 className="text-xl font-bold">Renewal signals</h3><p className="mt-1 text-sm text-slate-500">Evidence-based prompts only. Nothing renews automatically.</p><div className="mt-5 space-y-3">{signals.map((item,index)=><article key={`${item.client_package_id}-${item.signal}-${index}`} className="rounded-2xl bg-amber-50 p-4"><p className="text-xs font-bold text-amber-800">{item.signal.replaceAll('_',' ')}</p><p className="mt-1 font-semibold">{item.package_name}</p><p className="mt-1 text-xs text-amber-900">{clients.find(client=>String(client.id)===String(item.client_id))?.displayName||'Authorised client'} · ends {new Date(item.end_date).toLocaleDateString()}</p></article>)}{state==='ready'&&!signals.length&&<p className="rounded-2xl border border-dashed p-8 text-center text-sm text-slate-500">No renewal action is currently due.</p>}</div></section></div>
    {editor&&<Modal title={editor.item?'Edit package':'Create package'} onClose={()=>setEditor(null)}><form onSubmit={save} className="space-y-4"><Field label="Package name"><input required value={editor.form.name} onChange={e=>setEditor({...editor,form:{...editor.form,name:e.target.value}})}/></Field><Field label="Description"><textarea value={editor.form.description||''} onChange={e=>setEditor({...editor,form:{...editor.form,description:e.target.value}})}/></Field><div className="grid gap-3 sm:grid-cols-2"><Field label="Session allowance"><input required type="number" min="1" value={editor.form.session_allowance} onChange={e=>setEditor({...editor,form:{...editor.form,session_allowance:e.target.value}})}/></Field><Field label="Duration (days)"><input required type="number" min="1" value={editor.form.duration_days} onChange={e=>setEditor({...editor,form:{...editor.form,duration_days:e.target.value}})}/></Field><Field label="Optional price"><input type="number" min="0" step="0.01" value={editor.form.price} onChange={e=>setEditor({...editor,form:{...editor.form,price:e.target.value}})}/></Field><Field label="Currency"><input maxLength="3" value={editor.form.currency||'INR'} onChange={e=>setEditor({...editor,form:{...editor.form,currency:e.target.value.toUpperCase()}})}/></Field></div><label className="flex min-h-11 items-center gap-3 text-sm font-semibold"><input type="checkbox" checked={editor.form.active} onChange={e=>setEditor({...editor,form:{...editor.form,active:e.target.checked}})}/>Active for new assignments</label><Actions onCancel={()=>setEditor(null)} label="Save package"/></form></Modal>}
    {assignment&&<Modal title="Assign package to client" onClose={()=>setAssignment(null)}><form onSubmit={assign} className="space-y-4"><Field label="Client"><select required value={assignment.client_id} onChange={e=>setAssignment({...assignment,client_id:e.target.value})}><option value="">Select client</option>{clients.map(client=><option key={client.id} value={client.id}>{client.displayName}</option>)}</select></Field><div className="grid gap-3 sm:grid-cols-2"><Field label="Start date"><input required type="date" value={assignment.start_date} onChange={e=>setAssignment({...assignment,start_date:e.target.value})}/></Field><Field label="End date"><input required type="date" value={assignment.end_date} onChange={e=>setAssignment({...assignment,end_date:e.target.value})}/></Field><Field label="Sessions"><input required type="number" min="1" value={assignment.sessions_total} onChange={e=>setAssignment({...assignment,sessions_total:e.target.value})}/></Field><Field label="Renewal date"><input type="date" value={assignment.renewal_date} onChange={e=>setAssignment({...assignment,renewal_date:e.target.value})}/></Field></div><Field label="Notes"><textarea value={assignment.notes} onChange={e=>setAssignment({...assignment,notes:e.target.value})}/></Field><Actions onCancel={()=>setAssignment(null)} label="Assign package"/></form></Modal>}
  </div>;
}

export function ClientPackagePanel({clientId}){const [items,setItems]=useState(null);useEffect(()=>{listClientPackages(clientId).then(result=>setItems(result.items||[])).catch(()=>setItems([]));},[clientId]);if(items===null)return <p className="rounded-2xl bg-white p-8 text-center text-sm text-slate-500">Loading programme…</p>;if(!items.length)return <p className="rounded-2xl border border-dashed bg-white p-8 text-center text-sm text-slate-500">No package is assigned to this client.</p>;return <div className="grid gap-4 lg:grid-cols-2">{items.map(item=><article key={item.id} className="rounded-2xl border border-slate-200 bg-white p-5"><div className="flex justify-between gap-3"><h3 className="font-bold">{item.name}</h3><span className="rounded-full bg-blue-50 px-2 py-1 text-xs font-bold text-blue-700">{item.status}</span></div><p className="mt-2 text-sm text-slate-500">{new Date(item.start_date).toLocaleDateString()} – {new Date(item.end_date).toLocaleDateString()}</p><div className="mt-4 h-2 overflow-hidden rounded-full bg-slate-100"><div className="h-full bg-blue-600" style={{width:`${Math.min(100,(item.sessions_used/item.sessions_total)*100)}%`}}/></div><p className="mt-2 text-sm font-semibold">{item.sessions_used} used · {item.sessions_remaining} remaining</p><p className="mt-1 text-xs text-slate-500">{item.next_session?`Next session ${new Date(item.next_session).toLocaleString()}`:item.renewal_date?`Renewal review ${new Date(item.renewal_date).toLocaleDateString()}`:'No future session scheduled'}</p></article>)}</div>}
function Modal({title,onClose,children}){return <div className="fixed inset-0 z-[80] flex items-end bg-slate-950/50 sm:items-center sm:justify-center sm:p-4"><section role="dialog" aria-modal="true" className="max-h-[92dvh] w-full overflow-y-auto rounded-t-3xl bg-white p-5 sm:max-w-xl sm:rounded-3xl sm:p-6"><div className="mb-5 flex items-center justify-between"><h3 className="text-xl font-bold">{title}</h3><button aria-label="Close" onClick={onClose} className="grid h-11 w-11 place-items-center rounded-xl border"><X size={18}/></button></div>{children}</section></div>}
function Field({label,children}){return <label className="block text-sm font-semibold text-slate-700">{label}<span className="mt-2 block [&>*]:min-h-11 [&>*]:w-full [&>*]:rounded-xl [&>*]:border [&>*]:border-slate-200 [&>*]:bg-white [&>*]:p-3 [&>*]:outline-none">{children}</span></label>}
function Actions({onCancel,label}){return <div className="flex justify-end gap-2"><button type="button" onClick={onCancel} className="min-h-11 rounded-xl border px-4 font-semibold">Cancel</button><button className="min-h-11 rounded-xl bg-slate-950 px-4 font-semibold text-white">{label}</button></div>}
